import{_ as e,o as t,c as s,l as i,t as n,N as r}from"./chunks/framework.Gjrf2Eoj.js";const y=JSON.parse('{"title":"docker-image-tag | x-cmd man (docker man1) | Create a tag TARGET_IMAGE that refers to SOURCE_IMAGE","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-image-tag - Create a tag TARGET_IMAGE that refers to SOURCE_IMAGE","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-image-tag | x-cmd man (docker man1) | Create a tag TARGET_IMAGE that refers to SOURCE_IMAGE"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-image-tag - Create a tag TARGET_IMAGE that refers to SOURCE_IMAGE"}]]},"headers":[],"params":{"isMan":true,"man":"docker-image-tag","category":"docker man1","desc":"Create a tag TARGET_IMAGE that refers to SOURCE_IMAGE"},"relativePath":"docker/man1/docker-image-tag.md","filePath":"docker/man1/docker-image-tag.md"}'),o={name:"docker/man1/docker-image-tag.md"},h={class:"visually-hidden"},g=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-image-tag - Create a tag TARGET_IMAGE that refers to SOURCE_IMAGE</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker image tag SOURCE_IMAGE[:TAG] TARGET_IMAGE[:TAG]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Assigns a new alias to an image in a registry. An alias refers to the entire image name including the optional <strong>TAG</strong> after the &#39;:&#39;.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>NAME</strong> The image name which is made up of slash-separated name components, optionally prefixed by a registry hostname. The hostname must comply with standard DNS rules, but may not contain underscores. If a hostname is present, it may optionally be followed by a port number in the format <strong>:8080</strong>. If not present, the command uses Docker&#39;s public registry located at <strong>registry-1.docker.io</strong> by default. Name components may contain lowercase letters, digits and separators. A separator is defined as a period, one or two underscores, or one or more dashes. A name component may not start or end with a separator.</p><p><strong>TAG</strong> The tag assigned to the image to version and distinguish images with the same name. The tag name must be valid ASCII and may contain lowercase and uppercase letters, digits, underscores, periods and hyphens. A tag name may not start with a period or a hyphen and may contain a maximum of 128 characters.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h2 id="tagging-an-image-referenced-by-id" tabindex="-1">Tagging an image referenced by ID <a class="header-anchor" href="#tagging-an-image-referenced-by-id" aria-label="Permalink to &quot;Tagging an image referenced by ID&quot;">​</a></h2><p>To tag a local image with ID &quot;0e5574283393&quot; into the &quot;fedora&quot; repository with &quot;version1.0&quot;:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0e5574283393</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fedora/httpd:version1.0</span></span></code></pre></div><h2 id="tagging-an-image-referenced-by-name" tabindex="-1">Tagging an image referenced by Name <a class="header-anchor" href="#tagging-an-image-referenced-by-name" aria-label="Permalink to &quot;Tagging an image referenced by Name&quot;">​</a></h2><p>To tag a local image with name &quot;httpd&quot; into the &quot;fedora&quot; repository with &quot;version1.0&quot;:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> httpd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fedora/httpd:version1.0</span></span></code></pre></div><p>Note that since the tag name is not specified, the alias is created for an existing local version <strong>httpd:latest</strong>.</p><h2 id="tagging-an-image-referenced-by-name-and-tag" tabindex="-1">Tagging an image referenced by Name and Tag <a class="header-anchor" href="#tagging-an-image-referenced-by-name-and-tag" aria-label="Permalink to &quot;Tagging an image referenced by Name and Tag&quot;">​</a></h2><p>To tag a local image with name &quot;httpd&quot; and tag &quot;test&quot; into the &quot;fedora&quot; repository with &quot;version1.0.test&quot;:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> httpd:test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fedora/httpd:version1.0.test</span></span></code></pre></div><h2 id="tagging-an-image-for-a-private-repository" tabindex="-1">Tagging an image for a private repository <a class="header-anchor" href="#tagging-an-image-for-a-private-repository" aria-label="Permalink to &quot;Tagging an image for a private repository&quot;">​</a></h2><p>Before pushing an image to a private registry and not the central Docker registry you must tag it with the registry hostname and port (if needed).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0e5574283393</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myregistryhost:5000/fedora/httpd:version1.0</span></span></code></pre></div><h2 id="options-1" tabindex="-1">OPTIONS <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-h</strong>, <strong>--help</strong>[=false] help for tag</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-image(1)</strong></p>',27);function d(a,p,l,c,m,k){return t(),s("div",null,[i("h1",h,n(a.$params.man),1),g])}const f=e(o,[["render",d]]);export{y as __pageData,f as default};
